import{_ as l,o as e,c as t,am as i}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"G1 和 ZGC 垃圾回收器","description":"","frontmatter":{"title":"G1 和 ZGC 垃圾回收器","excerpt":"摘要","date":"2025-08-20 19:14:43","updated":"2025-08-20 19:14:43"},"headers":[],"relativePath":"基础/JVM/G1 和 ZGC 垃圾回收器.md","filePath":"基础/JVM/G1 和 ZGC 垃圾回收器.md","lastUpdated":null}'),r={name:"基础/JVM/G1 和 ZGC 垃圾回收器.md"};function o(d,a,n,c,s,h){return e(),t("div",null,[...a[0]||(a[0]=[i('<p>JVM垃圾回收是Java平台的核心特性之一，负责自动管理内存，避免开发人员手动释放内存。</p><p>随着Java技术的发展，JVM垃圾回收器也经历了多代演进。下面我将介绍主要的垃圾回收器，并重点讲述G1和ZGC。</p><h2 id="常见垃圾回收器" tabindex="-1">常见垃圾回收器 <a class="header-anchor" href="#常见垃圾回收器" aria-label="Permalink to &quot;常见垃圾回收器&quot;">​</a></h2><h3 id="serial收集器" tabindex="-1">Serial收集器 <a class="header-anchor" href="#serial收集器" aria-label="Permalink to &quot;Serial收集器&quot;">​</a></h3><ul><li>单线程收集器，工作时需要暂停所有应用线程(STW)</li><li>简单高效，适用于单CPU环境和内存小于100MB的场景</li><li>参数：<code>-XX:+UseSerialGC</code></li></ul><h3 id="parnew收集器" tabindex="-1">ParNew收集器 <a class="header-anchor" href="#parnew收集器" aria-label="Permalink to &quot;ParNew收集器&quot;">​</a></h3><ul><li>Serial收集器的多线程版本</li><li>常与CMS一起使用作为年轻代收集器</li><li>参数：<code>-XX:+UseParNewGC</code></li></ul><h3 id="parallel-scavenge-parallel-old" tabindex="-1">Parallel Scavenge/Parallel Old <a class="header-anchor" href="#parallel-scavenge-parallel-old" aria-label="Permalink to &quot;Parallel Scavenge/Parallel Old&quot;">​</a></h3><ul><li>注重吞吐量的多线程收集器</li><li>可以通过参数控制最大暂停时间或吞吐量</li><li>参数：<code>-XX:+UseParallelGC</code></li></ul><h3 id="cms-concurrent-mark-sweep" tabindex="-1">CMS (Concurrent Mark Sweep) <a class="header-anchor" href="#cms-concurrent-mark-sweep" aria-label="Permalink to &quot;CMS (Concurrent Mark Sweep)&quot;">​</a></h3><ul><li>以获取最短回收停顿时间为目标的收集器</li><li>采用标记-清除算法，并发进行大部分工作</li><li>缺点：内存碎片、CPU资源敏感、浮动垃圾</li><li>参数：<code>-XX:+UseConcMarkSweepGC</code></li><li>JDK9标记为废弃，JDK14正式移除</li></ul><blockquote><p>问题： 为什么CMS垃圾回收器被废弃并移除</p></blockquote><p><a href="/java-site/基础/JVM/为什么CMS垃圾回收器被废弃并移除.html">为什么CMS垃圾回收器被废弃并移除</a></p><h2 id="g1垃圾回收器-garbage-first" tabindex="-1">G1垃圾回收器(Garbage-First) <a class="header-anchor" href="#g1垃圾回收器-garbage-first" aria-label="Permalink to &quot;G1垃圾回收器(Garbage-First)&quot;">​</a></h2><h3 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h3><p>G1(Garbage-First)是Oracle JDK 7引入的垃圾回收器，设计目标是替代CMS收集器。在JDK 9中被设为默认垃圾收集器。</p><h3 id="内存布局" tabindex="-1">内存布局 <a class="header-anchor" href="#内存布局" aria-label="Permalink to &quot;内存布局&quot;">​</a></h3><p>G1将堆划分为大小相等的区域(Region)，每个区域大小通常为1MB-32MB。区域有四种类型：</p><ul><li>Eden区域：存放新分配对象</li><li>Survivor区域：存放幸存对象</li><li>Old区域：存放长期存活对象</li><li>Humongous区域：存放大对象(超过区域大小50%的对象)</li></ul><p>这种设计带来了显著优势：不再严格划分新生代和老年代的物理空间，可以动态调整各代的大小。</p><h3 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h3><p>G1收集器的工作过程可分为以下几个阶段：</p><ol><li><strong>初始标记(Initial Marking)</strong>：STW，标记GC Roots直接关联对象</li><li><strong>并发标记(Concurrent Marking)</strong>：与应用线程并发执行，标记整个堆中的存活对象</li><li><strong>最终标记(Final Marking/Remark)</strong>：STW，处理并发标记阶段遗留的标记任务</li><li><strong>筛选回收(Cleanup)</strong>：STW，对各个区域的回收价值和成本进行排序，根据用户期望的停顿时间制定回收计划，然后回收选定的区域</li></ol><h3 id="g1的核心特性" tabindex="-1">G1的核心特性 <a class="header-anchor" href="#g1的核心特性" aria-label="Permalink to &quot;G1的核心特性&quot;">​</a></h3><ol><li><strong>预测停顿模型</strong>：G1会根据历史数据预测每个区域的回收时间，优先回收价值最高(回收空间最大)的区域，实现用户设定的停顿目标(-XX:MaxGCPauseMillis)</li><li><strong>增量式垃圾回收</strong>：G1不需要一次性回收整个堆空间，而是每次只处理部分区域</li><li><strong>混合式回收(Mixed GC)</strong>：G1可以同时回收年轻代和部分老年代，避免了完整的老年代GC</li><li><strong>SATB(Snapshot-At-The-Beginning)算法</strong>：解决并发标记的问题，降低漏标可能性</li></ol><h3 id="g1的调优参数" tabindex="-1">G1的调优参数 <a class="header-anchor" href="#g1的调优参数" aria-label="Permalink to &quot;G1的调优参数&quot;">​</a></h3><ul><li><code>-XX:+UseG1GC</code>：启用G1</li><li><code>-XX:MaxGCPauseMillis=200</code>：设置期望的最大停顿时间(默认200ms)</li><li><code>-XX:G1HeapRegionSize=n</code>：设置Region大小，必须是2的幂，范围1MB-32MB</li><li><code>-XX:InitiatingHeapOccupancyPercent=45</code>：设置触发标记周期的堆占用阈值(默认45%)</li></ul><h3 id="g1的优势" tabindex="-1">G1的优势 <a class="header-anchor" href="#g1的优势" aria-label="Permalink to &quot;G1的优势&quot;">​</a></h3><ol><li>可预测的停顿时间，适合大内存、多核CPU环境</li><li>空间整合能力强，降低内存碎片产生</li><li>并发能力强，大部分工作与应用线程并发执行</li><li>适合堆内存较大(6GB+)的系统</li></ol><h2 id="zgc垃圾回收器-z-garbage-collector" tabindex="-1">ZGC垃圾回收器(Z Garbage Collector) <a class="header-anchor" href="#zgc垃圾回收器-z-garbage-collector" aria-label="Permalink to &quot;ZGC垃圾回收器(Z Garbage Collector)&quot;">​</a></h2><h3 id="基本概念-1" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念-1" aria-label="Permalink to &quot;基本概念&quot;">​</a></h3><p>ZGC是JDK 11引入的低延迟垃圾回收器，设计目标是将STW时间控制在10ms以内，即使堆内存达到TB级别。在JDK 15中已成为生产可用状态。</p><h3 id="内存布局-1" tabindex="-1">内存布局 <a class="header-anchor" href="#内存布局-1" aria-label="Permalink to &quot;内存布局&quot;">​</a></h3><p>ZGC将堆内存划分为大小不等的区域(Z Page)，根据大小分为：</p><ul><li>Small (2MB)</li><li>Medium (32MB)</li><li>Large (大于等于32MB)</li></ul><h3 id="核心技术" tabindex="-1">核心技术 <a class="header-anchor" href="#核心技术" aria-label="Permalink to &quot;核心技术&quot;">​</a></h3><ol><li><p><strong>着色指针(Colored Pointers)</strong>：</p><p>ZGC在64位指针中保留了一些位作为标记位，用于标记对象状态：</p><ul><li>Marked0/Marked1位：用于标记活跃对象</li><li>Remapped位：指示对象是否已经被重定位</li><li>Finalizable位：标记是否可终结</li></ul></li><li><p><strong>读屏障(Load Barrier)</strong>：</p><p>在应用程序访问对象引用时，ZGC会检查指针的标记位，必要时进行处理，确保应用始终能看到正确的引用</p></li><li><p><strong>并发处理</strong>： 几乎所有GC操作都在并发阶段完成，包括并发标记、并发重定位、并发引用处理等</p></li></ol><h3 id="zgc工作流程" tabindex="-1">ZGC工作流程 <a class="header-anchor" href="#zgc工作流程" aria-label="Permalink to &quot;ZGC工作流程&quot;">​</a></h3><ol><li><strong>并发标记(Concurrent Mark)</strong>：标记所有可达对象</li><li><strong>并发准备重定位(Concurrent Prepare for Relocate)</strong>：选择要清理的区域</li><li><strong>并发重定位(Concurrent Relocate)</strong>：将存活对象复制到新位置</li><li><strong>并发重映射(Concurrent Remap)</strong>：更新引用，指向对象的新位置</li></ol><p>整个过程中STW阶段极短，主要包括初始标记、最终标记等少量操作，大部分工作与应用线程并发执行。</p><h3 id="zgc的调优参数" tabindex="-1">ZGC的调优参数 <a class="header-anchor" href="#zgc的调优参数" aria-label="Permalink to &quot;ZGC的调优参数&quot;">​</a></h3><ul><li><code>-XX:+UseZGC</code>：启用ZGC</li><li><code>-XX:ZAllocationSpikeTolerance</code>：调整ZGC对内存分配速率突增的容忍度</li><li><code>-XX:ConcGCThreads</code>：并发GC线程数</li><li><code>-XX:ZCollectionInterval</code>：两次GC之间的最小时间间隔</li><li><code>-XX:ZFragmentationLimit</code>：内存碎片百分比阈值</li></ul><h3 id="zgc的优势" tabindex="-1">ZGC的优势 <a class="header-anchor" href="#zgc的优势" aria-label="Permalink to &quot;ZGC的优势&quot;">​</a></h3><ol><li>超低延迟：GC停顿时间不超过10ms，且与堆大小无关</li><li>可扩展性强：支持8MB-16TB的堆内存范围</li><li>高吞吐量：即使在TB级别堆上也能保持高吞吐量，只比吞吐量收集器低约15%</li><li>适合延迟敏感型应用：如金融交易、游戏服务器、实时数据处理系统</li></ol><h2 id="g1与zgc的对比" tabindex="-1">G1与ZGC的对比 <a class="header-anchor" href="#g1与zgc的对比" aria-label="Permalink to &quot;G1与ZGC的对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>G1</th><th>ZGC</th></tr></thead><tbody><tr><td>首次发布</td><td>JDK 7</td><td>JDK 11</td></tr><tr><td>默认GC</td><td>JDK 9+</td><td>否</td></tr><tr><td>停顿时间</td><td>预测停顿，通常在100-200ms</td><td>&lt;10ms，与堆大小无关</td></tr><tr><td>内存占用</td><td>相对较小</td><td>较高(约10-15%)</td></tr><tr><td>CPU开销</td><td>中等</td><td>较高</td></tr><tr><td>碎片处理</td><td>较好</td><td>极佳</td></tr><tr><td>适用场景</td><td>6GB-100GB的堆内存，可接受短暂停顿</td><td>超大堆内存，极低延迟要求</td></tr><tr><td>JVM参数</td><td><code>-XX:+UseG1GC</code></td><td><code>-XX:+UseZGC</code></td></tr></tbody></table><h2 id="选择建议" tabindex="-1">选择建议 <a class="header-anchor" href="#选择建议" aria-label="Permalink to &quot;选择建议&quot;">​</a></h2><ul><li>如果系统内存&lt;4GB，可以考虑使用ParallelGC</li><li>如果系统内存在4GB-8GB，且关注吞吐量，可以使用G1</li><li>如果系统对延迟非常敏感，且内存&gt;8GB，建议使用ZGC</li><li>企业级应用通常G1是较为均衡的选择，能满足大多数场景需求</li><li>金融、游戏等对延迟极为敏感的领域，ZGC是更好的选择</li></ul><h2 id="未来发展" tabindex="-1">未来发展 <a class="header-anchor" href="#未来发展" aria-label="Permalink to &quot;未来发展&quot;">​</a></h2><p>随着JDK的更新，ZGC正在不断完善。JDK 16中已经支持了ZGC的类卸载功能，JDK 17中又进一步优化了ZGC的性能。</p><p>未来，ZGC很可能会成为Java默认的垃圾收集器，特别是随着大内存系统的普及和低延迟需求的增加。</p>',51)])])}const g=l(r,[["render",o]]);export{u as __pageData,g as default};
